import { ExternalLink, FileCode2 } from "lucide-react";
import type { TFunction } from "@/i18n/dictionary";
import { getLeanReport, leanRegions, leanStatus, type LeanRegion } from "@/lib/content";
import { highlight } from "@/lib/highlight";
import { VerificationBadge } from "@/components/ui/Badges";

/** Link to the static page (generated by scripts/build-lean-bundles.mjs) that opens this file in the Lean web editor. */
export function webEditorUrl(file: string): string {
  return `/lean-open/${file.replace(/\.lean$/, "").replaceAll("/", "--")}.html`;
}

function findRegion(region?: string, decl?: string): LeanRegion | undefined {
  const regions = leanRegions();
  if (region) return regions.get(region);
  if (decl) {
    const r = getLeanReport()?.declarations.find((d) => d.name === decl)?.region;
    if (r) return regions.get(r);
    const short = decl.split(".").pop()!;
    return [...regions.values()].find((x) => x.id.endsWith(`.${short}`));
  }
  return undefined;
}

export async function LeanBlock({ t, decl, region, title }: { t: TFunction; decl?: string; region?: string; title?: string }) {
  const r = findRegion(region, decl);
  const report = getLeanReport();
  const declName = decl ?? report?.declarations.find((d) => d.region === region)?.name;
  const status = declName ? leanStatus(declName) : null;
  if (!r) {
    return (
      <div className="!mt-6 rounded-xl border border-dashed border-formal/40 px-5 py-4 font-sans text-sm text-muted" data-mode="F">
        Lean source for <code>{decl ?? region}</code> is not available yet. {t("verify.leanNotCompiled")}.
      </div>
    );
  }
  const html = await highlight(r.code, "lean4");
  const verified = status?.verified ?? false;
  return (
    <figure className="!mt-6 overflow-hidden rounded-xl border border-formal/25 bg-card font-sans shadow-[var(--shadow)]" data-mode="F">
      <figcaption className="flex flex-wrap items-center gap-2 border-b border-formal/20 bg-formal-soft/60 px-4 py-2.5">
        <FileCode2 size={15} className="text-formal" aria-hidden="true" />
        <span className="text-sm font-semibold text-ink">{title ?? declName?.split(".").pop() ?? r.id}</span>
        <span className="text-xs text-muted">Lean 4</span>
        <span className="ms-auto flex flex-wrap gap-1.5">
          {r.provenance && r.provenance !== "definition" && <span className="chip">{t(`verify.${r.provenance}`)}</span>}
          {status &&
            (verified ? (
              <VerificationBadge label="formally-verified" text={t("verify.formally-verified")} title={t("verify.leanCompiled", { toolchain: report?.toolchain ?? "" })} />
            ) : (
              <VerificationBadge label="incomplete" text={t("verify.leanNotCompiled")} />
            ))}
        </span>
      </figcaption>
      <div className="code-frame" dangerouslySetInnerHTML={{ __html: html }} />
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1 border-t border-line bg-paper-2/50 px-4 py-2 text-xs text-muted">
        {status?.found && (
          <span>
            {t("verify.axioms")}:{" "}
            <span className="font-mono text-ink-2" dir="ltr">
              {status.axioms.length ? status.axioms.join(", ") : t("verify.noAxioms")}
            </span>
          </span>
        )}
        <span className="font-mono" dir="ltr">
          formal/{r.file}
        </span>
        <a href={webEditorUrl(r.file)} target="_blank" rel="noopener noreferrer" className="link ms-auto inline-flex items-center gap-1">
          {t("verify.openInLean")} <ExternalLink size={12} aria-hidden="true" />
        </a>
      </div>
    </figure>
  );
}
